Un laboratorio mide cuánto tarda en procesar muestras. Con n multiplicado por 10 quiere saber cómo crece el tiempo.

function crecimiento(medidas) {
  const previa = medidas[medidas.length - 2][1];
  const ultima = medidas[medidas.length - 1][1];
  if (previa === ultima) return "constante";
  const factor = ultima / previa;
  if (factor <= 3) return "logarítmico";
  if (factor <= 30) return "lineal";
  return "cuadrático";
}
